// Official ImageResolver's bounded media operations, on DS Bot REST transport.
// Deliberately no local-file URL or arbitrary filesystem media support.
import dns from 'node:dns/promises';
import net from 'node:net';
import http from 'node:http';
import https from 'node:https';
import { Readable } from 'node:stream';
import { LarkClient } from './lark-client.ts';

const MAX_IMAGE_BYTES = 20 * 1024 * 1024;
const systemFetch = globalThis.fetch;
type ResolvedAddress = { address: string; family: number };
type Lookup = NonNullable<http.RequestOptions['lookup']>;
type ImageFetchOptions = { signal: AbortSignal; redirect: 'error'; lookup: Lookup };

const blockedIpv4 = new net.BlockList();
for (const [network, prefix] of [
  ['0.0.0.0', 8], ['10.0.0.0', 8], ['100.64.0.0', 10], ['127.0.0.0', 8],
  ['169.254.0.0', 16], ['172.16.0.0', 12], ['192.0.0.0', 24],
  ['192.0.2.0', 24], ['192.168.0.0', 16], ['198.18.0.0', 15],
  ['198.51.100.0', 24], ['203.0.113.0', 24], ['224.0.0.0', 4], ['240.0.0.0', 4],
] as const) blockedIpv4.addSubnet(network, prefix, 'ipv4');
const blockedIpv6 = new net.BlockList();
for (const [network, prefix] of [
  ['::', 128], ['::1', 128], ['::', 96], ['::ffff:0:0', 96],
  ['fc00::', 7], ['fe80::', 10], ['ff00::', 8], ['2001:db8::', 32],
] as const) blockedIpv6.addSubnet(network, prefix, 'ipv6');

function privateAddress(address: string): boolean {
  // Block every mapped/compatible IPv4-in-IPv6 address. Image URLs do not need
  // these transitional forms, and hexadecimal mapped loopbacks otherwise
  // bypass dotted-decimal string checks.
  const family = net.isIP(address);
  if (family === 4) return blockedIpv4.check(address, 'ipv4');
  if (family === 6) return blockedIpv6.check(address, 'ipv6');
  return true;
}
async function validateRemoteImage(raw: string): Promise<{ url: URL; selected: ResolvedAddress }> {
  const url = new URL(raw);
  if (url.protocol !== 'https:' && url.protocol !== 'http:') throw new Error('Only HTTP(S) image URLs are supported');
  if (url.username || url.password) throw new Error('Image URL credentials are not allowed');
  const hostname = url.hostname.startsWith('[') ? url.hostname.slice(1, -1) : url.hostname;
  const family = net.isIP(hostname);
  const addresses: ResolvedAddress[] = family ? [{ address: hostname, family }] : await dns.lookup(hostname, { all: true, verbatim: true });
  if (!addresses.length || addresses.some(({ address }) => privateAddress(address))) throw new Error('Private image URL is not allowed');
  return { url, selected: addresses[0] };
}
function fixedLookup(selected: ResolvedAddress): Lookup {
  return (_hostname, options, callback) => {
    if (options.all) callback(null, [selected]);
    else callback(null, selected.address, selected.family);
  };
}
// Native fetch has no portable lookup injection without a version-matched Undici
// dependency. Node's HTTP(S) transport keeps Host/SNI on the URL while pinning
// the socket to the address validated above. Replaced fetch implementations are
// still honored for existing tests and embedders.
async function pinnedFetch(raw: string, options: ImageFetchOptions): Promise<Response> {
  const url = new URL(raw);
  const hostname = url.hostname.startsWith('[') ? url.hostname.slice(1, -1) : url.hostname;
  const transport = url.protocol === 'https:' ? https : http;
  return new Promise((resolve, reject) => {
    const request = transport.request(url, {
      lookup: options.lookup,
      signal: options.signal,
      servername: net.isIP(hostname) ? undefined : hostname,
    }, incoming => {
      const headers = new Headers();
      for (const [name, value] of Object.entries(incoming.headers)) {
        if (Array.isArray(value)) for (const item of value) headers.append(name, item);
        else if (value !== undefined) headers.set(name, value);
      }
      const status = incoming.statusCode ?? 500;
      const body = status === 204 || status === 304 ? null : Readable.toWeb(incoming) as ReadableStream<Uint8Array>;
      const response = new Response(body, { status, headers });
      Object.defineProperty(response, 'url', { value: url.href });
      resolve(response);
    });
    request.once('error', reject);
    request.end();
  });
}
async function cancelResponse(response: Response): Promise<void> {
  try { await response.body?.cancel(); } catch { /* best-effort connection cleanup */ }
}
async function readLimitedBody(response: Response): Promise<Buffer> {
  const declared = Number(response.headers.get('content-length'));
  if (declared > MAX_IMAGE_BYTES) {
    await cancelResponse(response);
    throw new Error('Image is empty or exceeds 20 MiB');
  }
  if (!response.body) throw new Error('Image is empty or exceeds 20 MiB');
  const reader = response.body.getReader();
  const chunks: Buffer[] = [];
  let total = 0;
  try {
    while (true) {
      const { done, value } = await reader.read();
      if (done) break;
      total += value.byteLength;
      if (total > MAX_IMAGE_BYTES) throw new Error('Image is empty or exceeds 20 MiB');
      chunks.push(Buffer.from(value.buffer, value.byteOffset, value.byteLength));
    }
  } catch (error) {
    try { await reader.cancel(error); } catch { /* preserve the download error */ }
    throw error;
  } finally {
    reader.releaseLock();
  }
  if (!total) throw new Error('Image is empty or exceeds 20 MiB');
  return Buffer.concat(chunks, total);
}
export async function fetchRemoteImageBuffer(raw: string): Promise<Buffer> {
  const { url, selected } = await validateRemoteImage(raw);
  const fetchImpl = globalThis.fetch === systemFetch ? pinnedFetch : globalThis.fetch.bind(globalThis);
  const response = await fetchImpl(url.href, {
    signal: AbortSignal.timeout(15000),
    redirect: 'error',
    lookup: fixedLookup(selected),
  } as ImageFetchOptions);
  if (response.url && response.url !== url.href) {
    try { await validateRemoteImage(response.url); } finally { await cancelResponse(response); }
    throw new Error('Image redirects are not allowed');
  }
  if (response.status >= 300 && response.status < 400) {
    await cancelResponse(response);
    throw new Error('Image redirects are not allowed');
  }
  if (!response.ok) {
    await cancelResponse(response);
    throw new Error(`Image download failed (${response.status})`);
  }
  return readLimitedBody(response);
}
export async function uploadImageLark(params: { cfg: any; image: Buffer; imageType: string; accountId?: string }): Promise<{ imageKey: string }> {
  const response = await LarkClient.fromCfg(params.cfg, params.accountId).sdk.im.image.create({ data: { image_type: params.imageType, image: params.image } });
  const imageKey = response?.data?.image_key ?? response?.image_key;
  if (!imageKey) throw new Error('Feishu did not return an image_key');
  return { imageKey };
}
