import { StreamingCardController as OfficialCardController } from '../vendor/openclaw-lark/src/card/dsbot-streaming-card-controller.ts';
import {
  recordToolUseEnd,
  recordToolUseStart,
  startToolUseTraceRun,
} from './vendor/openclaw-lark/src/card/tool-use-trace-store.ts';
import { transformTerminalCardTables } from './src/native-tables.ts';
import type { LarkRuntimeConfig } from './src/runtime-config.ts';

/**
 * 终态卡宿主钩子（注入 vendor StreamingCardController，表格业务留在 src/）。
 * 与 vendor reply-dispatcher-types.ts 里 StreamingCardDeps.terminalCardHooks 同形。
 */
export interface TerminalCardHooks {
  transformTerminalCard?: (card: Record<string, unknown>) => Record<string, unknown>;
}

export interface NotificationCardState {
  cardMessageId: string | null;
  cardKitCardId: string | null;
  cardKitSequence: number;
}

export interface NotificationStreamOptions {
  uuid: string;
  state?: NotificationCardState;
  checkpoint(state: NotificationCardState): void;
}

export interface OfficialTurnController {
  readonly cardMessageId: string | null;
  readonly currentPhase: string;
  ensureCardCreated(): Promise<void>;
  onPartialReply(payload: { text: string }): Promise<void>;
  onReasoningStream(payload: { text: string }): Promise<void>;
  onDeliver(payload: { text: string }): Promise<void>;
  onToolStart(payload: { name: string; phase: 'start' }): Promise<void>;
  onToolPayload(payload: { text: string }): Promise<void>;
  onIdle(): Promise<void>;
  onError(error: unknown, info: { kind: string }): Promise<void>;
  abortCard(): Promise<void>;
  markFullyComplete(): void;
}

export type OfficialTurnControllerFactory = (deps: {
  cfg: LarkRuntimeConfig;
  agentId: string;
  sessionKey: string;
  accountId: string | undefined;
  chatId: string;
  replyToMessageId: string | undefined;
  notification?: NotificationStreamOptions;
  replyInThread: false;
  toolUseDisplay: {
    mode: 'on';
    showToolUse: true;
    showToolResultDetails: false;
    showFullPaths: false;
  };
  resolvedFooter: {
    status: false;
    elapsed: false;
    tokens: false;
    cache: false;
    context: false;
    model: false;
  };
  /** 终态卡变换钩子：native 表格模式由 bindTerminalTables 注入，markdown 模式缺省。 */
  terminalCardHooks?: TerminalCardHooks;
}) => OfficialTurnController;

const defaultFactory: OfficialTurnControllerFactory = (deps) =>
  new OfficialCardController(
    deps as unknown as ConstructorParameters<typeof OfficialCardController>[0],
  ) as OfficialTurnController;

/**
 * 按插件配置的 tableRenderMode 绑定终态卡钩子（模式唯一权威入口）：
 * - native：给每个 turn 的终态整卡挂 transformTerminalCardTables（markdown
 *   管道表格 → 原生 table 组件），vendor 控制器同时跳过内置代码块降级；
 * - markdown（缺省）：不注入钩子，行为与旧版完全一致。
 * base 缺省用官方 controller 直连工厂。
 */
export function bindTerminalTables(
  mode: 'markdown' | 'native',
  base?: OfficialTurnControllerFactory,
): OfficialTurnControllerFactory {
  const factory = base ?? defaultFactory;
  if (mode !== 'native') return factory;
  return (deps) =>
    factory({ ...deps, terminalCardHooks: { transformTerminalCard: transformTerminalCardTables } });
}

/** One official CardKit turn. No legacy card builder or legacy fallback exists here. */
export class OfficialTurnStream {
  private readonly controller: OfficialTurnController;
  private queue: Promise<void> = Promise.resolve();
  private traceStarted = false;

  constructor(
    private readonly sessionKey: string,
    chatId: string,
    replyToMessageId: string | undefined,
    cfg: LarkRuntimeConfig,
    factory: OfficialTurnControllerFactory = defaultFactory,
    accountId?: string,
    notification?: NotificationStreamOptions,
  ) {
    this.controller = factory({
      cfg,
      agentId: 'dsh',
      sessionKey,
      accountId,
      chatId,
      replyToMessageId,
      ...(notification ? { notification } : {}),
      replyInThread: false,
      toolUseDisplay: {
        mode: 'on',
        showToolUse: true,
        showToolResultDetails: false,
        showFullPaths: false,
      },
      resolvedFooter: {
        status: false,
        elapsed: false,
        tokens: false,
        cache: false,
        context: false,
        model: false,
      },
    });
  }

  get phase(): string {
    return this.controller.currentPhase;
  }

  get messageId(): string | null {
    return this.controller.cardMessageId;
  }

  private beginTrace(): void {
    if (this.traceStarted) return;
    startToolUseTraceRun(this.sessionKey);
    this.traceStarted = true;
  }

  async start(): Promise<void> {
    this.beginTrace();
    await this.controller.ensureCardCreated();
  }

  text(snapshot: string): Promise<void> {
    this.beginTrace();
    return this.enqueue(() => this.controller.onPartialReply({ text: snapshot }));
  }

  reasoning(_snapshot: string): Promise<void> {
    // DSH keeps reasoning available in its own session log; the Feishu card
    // intentionally presents only the answer and actual tool execution.
    return Promise.resolve();
  }

  toolStart(input: {
    name: string;
    callId: string | undefined;
    params: Record<string, unknown> | undefined;
  }): Promise<void> {
    return this.enqueue(async () => {
      this.beginTrace();
      recordToolUseStart({
        sessionKey: this.sessionKey,
        toolName: input.name,
        ...(input.callId !== undefined ? { toolCallId: input.callId } : {}),
        ...(input.params !== undefined ? { toolParams: input.params } : {}),
      });
      await this.controller.onToolStart({ name: input.name, phase: 'start' });
    });
  }

  toolEnd(input: {
    name: string;
    callId: string | undefined;
    params: Record<string, unknown> | undefined;
    result?: unknown;
    error: string | undefined;
    durationMs: number | undefined;
  }): Promise<void> {
    return this.enqueue(async () => {
      recordToolUseEnd({
        sessionKey: this.sessionKey,
        toolName: input.name,
        ...(input.callId !== undefined ? { toolCallId: input.callId } : {}),
        ...(input.params !== undefined ? { toolParams: input.params } : {}),
        result: input.result,
        ...(input.error !== undefined ? { error: input.error } : {}),
        ...(input.durationMs !== undefined ? { durationMs: input.durationMs } : {}),
      });
      await this.controller.onToolPayload({ text: '' });
    });
  }

  complete(answer: string): Promise<void> {
    this.beginTrace();
    return this.enqueue(async () => {
      // A committed message is already a partial snapshot in the controller.
      // Only commit it here; never append it a second time on terminal retry.
      if (answer.trim() && this.phase !== 'completed') await this.controller.onDeliver({ text: answer });
      this.controller.markFullyComplete();
      await this.controller.onIdle();
    });
  }

  fail(error: unknown): Promise<void> {
    return this.enqueue(() => this.controller.onError(error, { kind: 'turn' }));
  }

  abort(): Promise<void> {
    return this.enqueue(() => this.controller.abortCard());
  }

  private enqueue(operation: () => Promise<void>): Promise<void> {
    const next = this.queue.then(operation, operation);
    this.queue = next.catch(() => {});
    return next;
  }
}
