// Small logger adapter for the bundled official controller.
let provider: any;
export function setLoggerProvider(value: any): void { provider = value; }
export function larkLogger(subsystem: string) {
  const fallback = {
    debug: (...args: any[]) => console.debug(`[feishu/${subsystem}]`, ...args),
    info: (...args: any[]) => console.log(`[feishu/${subsystem}]`, ...args),
    warn: (...args: any[]) => console.warn(`[feishu/${subsystem}]`, ...args),
    error: (...args: any[]) => console.error(`[feishu/${subsystem}]`, ...args),
  };
  return {
    subsystem,
    debug: (message: string, meta?: any) => (provider?.logging?.getChildLogger?.({ subsystem }) ?? provider?.logger ?? fallback).debug?.(message, meta),
    info: (message: string, meta?: any) => (provider?.logging?.getChildLogger?.({ subsystem }) ?? provider?.logger ?? fallback).info?.(message, meta),
    warn: (message: string, meta?: any) => (provider?.logging?.getChildLogger?.({ subsystem }) ?? provider?.logger ?? fallback).warn?.(message, meta),
    error: (message: string, meta?: any) => (provider?.logging?.getChildLogger?.({ subsystem }) ?? provider?.logger ?? fallback).error?.(message, meta),
    child: (name: string) => larkLogger(`${subsystem}/${name}`),
  };
}
