/**
 * 终态卡片把 markdown 管道表格转成飞书原生 table 组件（Card JSON 2.0）。
 *
 * 这是 DSH 自有业务定制（2026-11-07 自 vendor/openclaw-lark/src/card/native-tables.ts
 * 外移）：经 src/streaming.ts 的 bindTerminalTables() 以 terminalCardHooks 注入
 * vendor StreamingCardController 的终态整卡更新，vendor 不再感知表格业务。
 *
 * 背景：CardKit 流式阶段只有一个 markdown element，表格必须保持 inline；
 * 终态整卡更新时才能换成原生组件。此前 dist/card/native-tables.js 是
 * 没有 TS 源的编译孤儿、从未接入运行时。实现补上用户定调的三点：
 *   1. 列宽按「字符数 → 固定像素」自动算，冻结首列、允许横向滚动；
 *      服务端拿不到客户端画布宽度，不再猜窗口：每列按内容自然宽、下限取官方
 *      80px，超出的部分由客户端横向滑动查看（PC 留白可接受，手机不再被压成省略号）。
 *      固定像素不会被客户端等比压窄，故无需再加高下限来「防压缩」。
 *   2. 自动推断 number / options 数据类型，数字右对齐 + 千分位；
 *   3. 超过单卡预算的表格转成可读列表（不是代码块），信息不丢。
 *
 * 官方约束：单卡最多 5 个 table 组件；page_size 1..10（每页最多 10 行）；
 * width 支持 auto / 固定像素 [80px,600px] / 百分比 [1%,100%]。
 * 单元格空间不足时原生 table 只截断不换行，故固定像素下限必须足够放内容；
 * 长叙述型表格（isProseTable）保留 2.0 富文本，不转成会截断的组件。
 * 本模块默认仍守 markdown 时代实测的预算 3（FEISHU_CARD_TABLE_LIMIT），
 * 只有显式给 maxTables 时才会放宽，避免与既有 11310 兜底口径打架。
 */

import { larkLogger } from '../vendor/openclaw-lark/dist/core/lark-logger.js';
import { FEISHU_CARD_TABLE_LIMIT, findMarkdownTablesOutsideCodeBlocks } from '../vendor/openclaw-lark/dist/card/card-error.js';

const log = larkLogger('card/native-tables');

// ---------------------------------------------------------------------------
// 字符宽度 → 自然权重
// ---------------------------------------------------------------------------

export interface ParsedTable {
  headers: string[];
  rows: string[][];
}

/** 一个全角字符≈2px 单位、半角≈1px 单位。 */
export function displayWidth(text: string): number {
  let units = 0;
  for (const ch of text) {
    // CJK / 全角标点 / 常见中文符号按 2 计，其余按 1 计。
    units += /[\u1100-\u115f\u2e80-\ua4cf\uac00-\ud7a3\uf900-\ufaff\ufe10-\ufe6f\uff01-\uff60\u3000-\u303f]/.test(ch) ? 2 : 1;
  }
  return units;
}

/** 去掉 markdown 装饰，避免 `**加粗**` / 反引号把列宽算大。 */
export function plain(value: string): string {
  return value
    .replace(/\*\*([^*]+)\*\*/g, '$1')
    .replace(/`([^`]+)`/g, '$1')
    .replace(/!\[([^\]]*)\]\([^)]*\)/g, '$1')
    .trim();
}

/** 官方 width 下限 80px；自然权重上限 600px。 */
const MIN_WIDTH_PX = 80;
const MAX_WIDTH_PX = 600;
/**
 * 卡片正文 14px：半角≈7px、全角≈14px。displayWidth() 已把全角记为 2 单位，
 * 故每单位 7px。旧值 14px/单位把中文按 28px/字算，是「表头过宽」的根因。
 */
const PX_PER_UNIT = 7;
const PADDING_PX = 28;
/**
 * 单列参考宽度上限（displayWidth 单位，约 13 个中文字/行）。
 * 原生 table 单元格放不下长内容时是「截断」而非换行（官方文档），把整段
 * 长文本算进列宽只会得到一列 600px、其余列 80px 的畸形排版。故按 p75 +
 * 参考上限给自然权重，超长内容由 isProseTable 分流回富文本。
 */
const REF_UNITS = 26;
/** 单元格超过此长度（约 24 个中文字）视为叙述型，原生组件会截断，保留富文本。 */
const PROSE_CELL_UNITS = 48;
/**
 * 统一固定像素布局（用户定调 2026-11-07：首列固定、其余可横向滑动）。
 * 服务端拿不到客户端画布宽度，不再用百分比猜窗口：每列按内容给固定像素，
 * 下限取官方 80px、上限 240px 避免单列独占。总宽超出画布时由客户端横向
 * 滚动，首列始终冻结。
 *
 * 注意：固定像素**不会**被客户端等比压窄（这正是百分比在手机翻车的原因），
 * 所以不需要人为抬高下限来「防压缩」。此前 112px 下限把「板块/方向/涨跌幅」
 * 这类 2~3 字表头硬撑宽 30+px（用户反馈「表头宽度太宽」），改回按内容自然宽。
 */
const MIN_COL_PX = MIN_WIDTH_PX;  // 80px = 官方下限，列宽由内容主导
const MAX_COL_PX = 240;
const MAX_SPREAD = 2.2;    // 均衡化后最宽/最窄列的最大比值

function cellUnits(text: string): number {
  return displayWidth(plain(text));
}

function naturalWidthPx(header: string, cells: readonly string[]): number {
  const headerUnits = Math.min(Math.max(cellUnits(header), 1), REF_UNITS);
  const sorted = cells.map(cellUnits).sort((a, b) => a - b);
  // 用 p75 而非 max：单个超长单元格不该把整列顶到 600px。
  const p75 = sorted.length ? sorted[Math.floor((sorted.length - 1) * 0.75)] ?? headerUnits : headerUnits;
  const units = Math.min(Math.max(headerUnits, p75), REF_UNITS);
  return Math.min(Math.max(units * PX_PER_UNIT + PADDING_PX, MIN_WIDTH_PX), MAX_WIDTH_PX);
}

/** 单列自然宽（保留导出，供外部/单测单独校验标定）。 */
export function columnWidthPx(header: string, cells: readonly string[]): string {
  return `${naturalWidthPx(header, cells)}px`;
}

/**
 * 叙述型表格：多数单元格是长段落。原生 table 单元格不换行、超长截断，
 * 转成组件反而丢信息、观感散乱；这类表保留 2.0 富文本（会换行渲染）。
 */
export function isProseTable(parsed: ParsedTable): boolean {
  const cells = parsed.rows.flat();
  if (!cells.length) return false;
  const long = cells.filter((c) => cellUnits(c) > PROSE_CELL_UNITS).length;
  return long > 0 && long / cells.length >= 0.34;
}

/**
 * 统一固定像素布局（用户定调 2026-11-07）：所有表格一律按内容给固定像素列宽，
 * 首列冻结、宽度超出画布时由客户端横向滑动查看。
 *
 * 为什么不再用百分比铺满：服务端同一份卡片 JSON 发给所有端，拿不到客户端
 * 画布宽度。PC 上 25% 约 200px 够放 4 个中文字，手机上约 90px 只够 2~3 个，
 * 而原生 table 单元格空间不足时是**截断**（不换行），聊天流窄卡片四列全变
 * 省略号。固定像素让每列 ≥ MIN_COL_PX，手机上内容也不被压没；代价只是 PC
 * 宽屏留白或需要横滑——按用户定调「实际上都不影响」，优先保住信息完整。
 */
export interface TableLayout {
  widths: string[];
  /** 恒 true：所有表格都允许横向滚动、都冻结首列。 */
  scroll: boolean;
}

/** 列间均衡化：把最宽/最窄的比收敛到 MAX_SPREAD 内，保持总宽不变。 */
function equalize(widths: number[]): number[] {
  let out = [...widths];
  for (let pass = 0; pass < 3; pass++) {
    const min = Math.min(...out);
    const max = Math.max(...out);
    if (max <= min * MAX_SPREAD) break;
    const floor = Math.max(MIN_COL_PX, Math.round(max / MAX_SPREAD));
    const ceil = Math.min(MAX_COL_PX, Math.round(min * MAX_SPREAD));
    const targetSum = out.reduce((a, b) => a + b, 0);
    out = out.map((w) => Math.min(Math.max(w, floor), ceil));
    const delta = targetSum - out.reduce((a, b) => a + b, 0);
    if (delta > 0) {
      const room = out.map((w) => ceil - w);
      const roomSum = room.reduce((a, b) => a + b, 0);
      if (roomSum > 0) out = out.map((w, i) => w + Math.round(delta * ((room[i] ?? 0) / roomSum)));
    } else if (delta < 0) {
      const room = out.map((w) => w - floor);
      const roomSum = room.reduce((a, b) => a + b, 0);
      if (roomSum > 0) out = out.map((w, i) => w + Math.round(delta * ((room[i] ?? 0) / roomSum)));
    }
  }
  return out;
}

export function tableLayout(parsed: ParsedTable): TableLayout {
  const natural = parsed.headers.map((header, i) =>
    naturalWidthPx(header, parsed.rows.map((row) => row[i] ?? '')));
  const px = equalize(natural);
  return {
    // 逐列钳到 [MIN_COL_PX, MAX_COL_PX]：短列放得下内容，宽列不独占整表。
    widths: px.map((w) => `${Math.min(Math.max(w, MIN_COL_PX), MAX_COL_PX)}px`),
    scroll: true,
  };
}

/** 便捷导出：只取列宽（单测/外部校验用）。 */
export function tableWidths(parsed: ParsedTable): string[] {
  return tableLayout(parsed).widths;
}

// ---------------------------------------------------------------------------
// 数据类型推断
// ---------------------------------------------------------------------------

export interface NativeColumn {
  name: string;
  display_name: string;
  data_type: 'text' | 'lark_md' | 'number' | 'options';
  width: string;
  /** 官方 column 字段；horizontal_align 统一 left（见 tableColumns 注释）。 */
  horizontal_align: 'left' | 'right';
  vertical_align: 'top';
  format?: { precision: number; separator: boolean };
}

/** 纯数字（允许 +/-、千分位、小数、百分号、亿/万单位后缀）。 */
const NUMERIC_RE = /^[+-]?\d[\d,]*(\.\d+)?%?([亿万千])?$/;

/** 有界枚举列（方向/状态等短词），转成带色的 options 标签。 */
const OPTION_VALUES: Record<string, string> = {
  '涨': 'red', '跌': 'green', '平': 'grey',
  '买': 'red', '卖': 'green', '多': 'red', '空': 'green',
  '是': 'green', '否': 'red', '有': 'green', '无': 'grey',
  '成功': 'green', '失败': 'red', '启用': 'green', '停用': 'grey',
};

function inferColumnType(header: string, cells: readonly string[]): NativeColumn['data_type'] {
  const values = cells.map(plain).filter(Boolean);
  if (!values.length) return 'text';

  // 数字列：全部单元格都是数值形态，且至少 1 个含小数点、或表头是数值语义，
  // 才判 number，避免把「年份/代码/序号」误当金额。
  // 含 % / 亿 / 万 的列保持 text：number 组件会丢掉符号与单位，属信息损失。
  if (values.every((v) => NUMERIC_RE.test(v.replace(/\s/g, ''))) && !values.some((v) => /[%亿万千]/.test(v))) {
    const looksDecimal = values.some((v) => /\./.test(v));
    const numericHeader = /价|额|幅|率|量|值|点|涨|跌|净|流入|流出|成交|市值|收益|成本|数$/.test(plain(header));
    if (looksDecimal || numericHeader) return 'number';
  }

  const distinct = new Set(values);
  if (distinct.size <= 4 && values.every((v) => v.length <= 4) && [...distinct].every((v) => v in OPTION_VALUES)) {
    return 'options';
  }

  // 单元格里带 markdown 链接/加粗/表情时保留 lark_md，否则纯文本更安全。
  return values.some((v) => /\[[^\]]+\]\([^)]*\)|<[^>]+>|@\w+/.test(v)) ? 'lark_md' : 'text';
}

function precisionOf(cells: readonly string[]): number {
  let max = 0;
  for (const cell of cells) {
    const digits = /\.(\d+)/.exec(plain(cell))?.[1];
    if (digits) max = Math.max(max, digits.length);
  }
  return Math.min(Math.max(max, 0), 4);
}

// ---------------------------------------------------------------------------
// markdown 管道表格解析
// ---------------------------------------------------------------------------

/** 解析标准 pipe table；非法（列数不齐/无分隔行/超 50 列）返回 null，原样保留 markdown。 */
export function parseMarkdownTable(raw: string): ParsedTable | null {
  // optimizeMarkdownStyle 会在表格前后插 <br> / 空行；只保留表格行，忽略杂行。
  const lines = raw
    .split(/\r?\n/)
    .map((l) => l.trim())
    .filter((l) => l.startsWith('|') && l.endsWith('|'));
  if (lines.length < 3) return null;
  const [headerLine, separatorLine] = lines;
  if (!headerLine || !separatorLine) return null;
  if (!/^\|(?:\s*:?-+:?\s*\|)+$/.test(separatorLine)) return null;
  // 单元格内的 `\|` 是转义管道，不能当列分隔符切开（否则列数不齐、整表降级）。
  // 用 lookbehind 按未转义管道切分，再把 `\|` 还原成字面 `|`。
  const cells = (line: string): string[] =>
    line.slice(1, -1).split(/(?<!\\)\|/).map((c) => c.trim().replace(/\\\|/g, '|'));
  const headers = cells(headerLine);
  if (!headers.length || headers.length > 50 || headers.some((h) => !h)) return null;
  // 分隔行的列数必须与表头一致（否则是残缺表，保留 markdown 原文而非猜列）。
  if (cells(separatorLine).length !== headers.length) return null;
  const rows = lines.slice(2).map(cells);
  if (rows.some((row) => row.length !== headers.length)) return null;
  return { headers, rows };
}

/** markdown 表格分隔行（整行 `|---|---|` 形态，含 :---: / ---: 变体）。 */
const SEPARATOR_LINE_RE = /^\|(?:\s*:?-+:?\s*\|)+$/;

/**
 * 把 markdown 表格分隔行统一改写成显式左对齐 `:---`（用户定调 2026-11-08：
 * 列对齐全局统一，不按数据类型混排；显式 ---:/:---: 也归一到 left）。
 * 应用于终态卡里残留为 markdown 的表格（长叙述/超预算不转组件的）；
 * 渲染器若不支持对齐语法则无效果、无损。代码块内的分隔行是字面内容，不动。
 */
export function normalizeTableSeparators(content: string): string {
  if (!content.includes('|')) return content;
  let changed = false;
  let inFence = false;
  const lines = content.split(/\r?\n/).map((line) => {
    if (/^\s*(```|~~~)/.test(line)) {
      inFence = !inFence;
      return line;
    }
    if (inFence) return line;
    const t = line.trim();
    if (!SEPARATOR_LINE_RE.test(t)) return line;
    changed = true;
    const count = t.slice(1, -1).split('|').length;
    return `|${Array.from({ length: count }, () => ' :--- ').join('|')}|`;
  });
  return changed ? lines.join('\n') : content;
}

function tableColumns(parsed: ParsedTable, widths: string[]): NativeColumn[] {
  return parsed.headers.map((header, i) => {
    const cells = parsed.rows.map((row) => row[i] ?? '');
    const type = inferColumnType(header, cells);
    const col: NativeColumn = {
      name: `c${i}`,
      display_name: plain(header),
      data_type: type,
      width: widths[i] ?? `${MIN_COL_PX}px`,
      // 列对齐全局统一左对齐（用户定调 2026-11-08）：官方对 number 列默认右对齐、
      // 文本左对齐，同表混排观感差；显式覆盖成与表头一致的 left。
      horizontal_align: 'left',
      vertical_align: 'top',
    };
    if (type === 'number') col.format = { precision: precisionOf(cells), separator: true };
    return col;
  });
}

/** 单张原生 table 组件。page_size 钳到官方 1..10。 */
export function buildNativeTable(parsed: ParsedTable): Record<string, unknown> {
  const layout = tableLayout(parsed);
  const columns = tableColumns(parsed, layout.widths);
  const rows = parsed.rows.map((row) =>
    Object.fromEntries(row.map((cell, i) => {
      // ParsedTable 已保证 rows 与 headers 等宽，columns 按 headers 建，索引必命中。
      const col = columns[i]!;
      const value = plain(cell);
      if (col.data_type === 'options') {
        const color = OPTION_VALUES[value] ?? 'blue';
        return [col.name, [{ text: value, color }]];
      }
      return [col.name, col.data_type === 'number' ? Number(value.replace(/[,%亿万]/g, '')) || 0 : value];
    })),
  );
  return {
    tag: 'table',
    page_size: Math.min(Math.max(parsed.rows.length, 1), 10),
    row_height: 'low',
    // 统一冻结首列：宽度超出画布时横向滑动，首列始终可见（用户定调）。
    freeze_first_column: true,
    header_style: {
      text_align: 'left', text_size: 'normal', background_style: 'grey',
      text_color: 'default', bold: true, lines: 1,
    },
    columns,
    rows,
  };
}

/** 超预算表格的可读降级：表头标一次、按行分块，宽表不挤成一行。 */
export function readableTable(parsed: ParsedTable): string {
  const headers = parsed.headers.map(plain);
  return parsed.rows
    .map((row) => `- ${headers.map((h, i) => `**${h}**：${plain(row[i] ?? '')}`).join('；')}`)
    .join('\n');
}

// ---------------------------------------------------------------------------
// 整卡转换
// ---------------------------------------------------------------------------

export interface NativeTableOptions {
  /** 单卡最多渲染成原生组件的表格数；默认沿用 markdown 实测预算 3。 */
  maxTables?: number;
}

type CardLike = { body?: { elements?: Array<Record<string, unknown>> }; elements?: Array<Record<string, unknown>>; [key: string]: unknown };

/** optimizeMarkdownStyle 插的纯占位行不值得单独占一个 element。 */
function meaningful(text: string): boolean {
  const t = text.replace(/<br\s*\/?>/gi, '').trim();
  return t.length > 0;
}

/**
 * 把终态卡片 body.elements 里的 markdown 管道表格换成原生 table 组件。
 *
 * - 只对 `tag: 'markdown'` 且 content 是字符串的元素生效；其它组件原样保留。
 * - 表格前后的普通文本仍按 markdown 元素输出（顺序保持不变）。
 * - 超过 maxTables 的表格转成可读列表（仍是 markdown 文本），信息不丢。
 * - 代码块里的表格不会被误转（findMarkdownTablesOutsideCodeBlocks 已排除）。
 */
export function convertMarkdownTablesToNative(card: CardLike, options: NativeTableOptions = {}): CardLike {
  // The CardKit controller supplies its terminal card with top-level elements;
  // ordinary interactive cards wrap them in body. Both shapes are supported.
  const body = card.body ?? card;
  if (!body?.elements) return card;
  const maxTables = options.maxTables ?? FEISHU_CARD_TABLE_LIMIT;

  let remaining = maxTables;
  let hasTable = false;
  const elements: Array<Record<string, unknown>> = [];
  for (const element of body.elements) {
    if (element.tag !== 'markdown' || typeof element.content !== 'string') {
      elements.push(element);
      continue;
    }
    const text = element.content;
    const rawMatches = findMarkdownTablesOutsideCodeBlocks(text);
    if (!rawMatches.length) {
      elements.push(element);
      continue;
    }

    // 逐段推进：转换成功的表格替换成组件/可读列表，其余（含非法表格、
    // 代码块、普通文本）原样保留，绝不吞掉或重复任何一段。
    let cursor = 0;
    let elementHadTable = false;
    for (const match of rawMatches) {
      const parsed = parseMarkdownTable(match.raw);
      // 非法表格 / 长叙述表格都不转组件：前者猜不了列，后者原生单元格会截断，
      // 都原样留在富文本里（2.0 会换行渲染），信息不丢。
      if (!parsed || isProseTable(parsed)) continue;
      const before = text.slice(cursor, match.index);
      if (meaningful(before)) elements.push({ ...element, content: before.trim() });
      if (remaining > 0) {
        elements.push(buildNativeTable(parsed));
        remaining -= 1;
        hasTable = true;
      } else {
        elements.push({ ...element, content: readableTable(parsed) });
      }
      elementHadTable = true;
      cursor = match.index + match.length;
    }
    if (!elementHadTable) {
      elements.push(element);
      continue;
    }
    const tail = text.slice(cursor);
    if (meaningful(tail)) elements.push({ ...element, content: tail.trim() });
  }
  // 残留为 markdown 的表格（长叙述/超预算/非法）分隔行统一显式左对齐，
  // 与原生表格列的对齐策略一致；未匹配表格的元素也顺带归一。
  let separatorsChanged = false;
  const normalized = elements.map((element) => {
    if (element.tag !== 'markdown' || typeof element.content !== 'string') return element;
    const content = normalizeTableSeparators(element.content);
    if (content === element.content) return element;
    separatorsChanged = true;
    return { ...element, content };
  });
  return hasTable || separatorsChanged ? (card.body ? { ...card, body: { ...body, elements: normalized } } : { ...card, elements: normalized }) : card;
}

/**
 * 宿主终态卡变换（经 src/streaming.ts 的 bindTerminalTables 注入 vendor
 * StreamingCardController 的 terminalCardHooks.transformTerminalCard）：
 * markdown 管道表格 → 原生 table 组件，并打诊断日志。
 */
export function transformTerminalCardTables(kit: Record<string, unknown>): Record<string, unknown> {
  const converted = convertMarkdownTablesToNative(kit) as Record<string, unknown>;
  try {
    const elements = ((converted as { body?: { elements?: unknown[] } }).body?.elements
      ?? (converted as { elements?: unknown[] }).elements ?? []) as Array<Record<string, unknown>>;
    const tableEls = elements.filter((el) => el?.tag === 'table') as Array<{ columns?: Array<{ width?: string }> }>;
    log.info('native-table terminal elements', {
      mode: 'native',
      total: elements.length,
      tables: tableEls.length,
      tags: elements.map((el) => String(el?.tag ?? '?')).slice(0, 12),
      widths: tableEls.map((t) => (t.columns ?? []).map((c) => c.width).join('/')).slice(0, 3),
    });
  } catch { /* diagnostic only */ }
  return converted;
}
