import { LarkClient } from './lark-client.ts';

function targetType(id: string) {
  if (id.startsWith('oc_')) return 'chat_id';
  if (id.startsWith('ou_')) return 'open_id';
  return 'user_id';
}
export async function sendCardFeishu(params: any) {
  const client = LarkClient.fromCfg(params.cfg, params.accountId).sdk;
  const data = { content: JSON.stringify(params.card), msg_type: 'interactive' };
  const response = params.replyToMessageId
    ? await client.im.message.reply({ path: { message_id: params.replyToMessageId }, data: { ...data, reply_in_thread: params.replyInThread === true } })
    : await client.im.message.create({ params: { receive_id_type: targetType(params.to), ...(params.uuid ? { uuid: params.uuid } : {}) }, data: { ...data, receive_id: params.to } });
  return { messageId: response?.data?.message_id ?? '', chatId: response?.data?.chat_id ?? '' };
}
export async function updateCardFeishu(params: any) {
  await LarkClient.fromCfg(params.cfg, params.accountId).sdk.im.message.patch({ path: { message_id: params.messageId }, data: { content: JSON.stringify(params.card) } });
}
