// DS Bot-owned account cache for the official card helpers.
// No OpenClaw channel, session controller, generated Lark SDK, or websocket.
const clients = new Map<string, any>();
let runtime: any = null;

export function getResolvedConfig(cfg: any, accountId?: string) {
  const root = cfg?.channels?.feishu ?? {};
  const base = { ...root };
  delete base.accounts;
  const id = String(accountId ?? 'default').trim().toLowerCase() || 'default';
  const override = root.accounts?.[id] ?? {};
  const merged = { ...base, ...override };
  for (const [key, value] of Object.entries(override)) {
    if (value && typeof value === 'object' && !Array.isArray(value) && base[key] && typeof base[key] === 'object' && !Array.isArray(base[key])) {
      merged[key] = { ...base[key], ...value };
    }
  }
  return merged;
}

export class LarkClient {
  private static cache = clients;
  public _sdk: any;
  private constructor(public readonly account: any) {}
  static fromCfg(cfg: any, accountId?: string): LarkClient {
    const id = String(accountId ?? 'default').trim().toLowerCase() || 'default';
    const config = getResolvedConfig(cfg, id);
    const account = {
      accountId: id, appId: config.appId, appSecret: config.appSecret,
      brand: config.domain ?? 'feishu', config,
      configured: Boolean(config.appId && config.appSecret),
      enabled: config.enabled !== false,
    };
    let client = clients.get(id);
    if (!client || client.account.appId !== account.appId || client.account.appSecret !== account.appSecret) {
      client = new LarkClient(account);
      clients.set(id, client);
    }
    return client;
  }
  static fromAccount(account: any): LarkClient {
    return LarkClient.fromCfg({ channels: { feishu: { ...account.config, appId: account.appId, appSecret: account.appSecret, domain: account.brand } } }, account.accountId);
  }
  static setRuntime(value: any): void { runtime = value; }
  static getRuntime(): any { return runtime; }
  get sdk(): any { return this._sdk; }
  dispose(): void {}
}
